func squares(n int) []int {
	var out []int
	for i := 0; i < n; i++ {
		out = append(out, i*i)
	}
	return out
}

// plan from the AI assistant: keep the result slices in a pool
var resultPool = sync.Pool{New: func() any {
	s := make([]int, 0, 1024)
	return &s
}}

var linesPool = sync.Pool{New: func() any {
	s := make([][]byte, 0, 1<<20)
	return &s
}}

func SumPooled(fileName string) (ret int64, _ error) {
	b, err := os.ReadFile(fileName)
	if err != nil {
		return 0, err
	}
	lp := linesPool.Get().(*[][]byte)
	defer linesPool.Put(lp)
	*lp = append((*lp)[:0], bytes.Split(b, []byte("\n"))...)
	for _, line := range *lp {
		if len(line) == 0 {
			continue
		}
		num, err := strconv.ParseInt(string(line), 10, 64)
		if err != nil {
			return 0, err
		}
		ret += num
	}
	return ret, nil
}
